import{_ as e,o as i,c as s,ag as t}from"./chunks/framework.DMXcdKmJ.js";const u=JSON.parse('{"title":"快速安装","description":"使用完整离线安装包完成 InduFrame 中心的安装、更新或卸载。","frontmatter":{"title":"快速安装","description":"使用完整离线安装包完成 InduFrame 中心的安装、更新或卸载。","status":"reviewed","kind":"how-to"},"headers":[],"relativePath":"zh/installation/quick-install.md","filePath":"zh/安装运维/快速安装.md"}'),o={name:"zh/installation/quick-install.md"};function l(d,a,n,c,p,h){return i(),s("div",null,[...a[0]||(a[0]=[t('<h1 id="快速安装" tabindex="-1">快速安装 <a class="header-anchor" href="#快速安装" aria-label="Permalink to &quot;快速安装&quot;">​</a></h1><p>本页介绍 InduFrame v1.0 的安装、更新和卸载。安装需要 Linux 服务器及具备系统管理权限的账号。</p><h2 id="安装前" tabindex="-1">安装前 <a class="header-anchor" href="#安装前" aria-label="Permalink to &quot;安装前&quot;">​</a></h2><p>将适用于服务器的安装包上传到服务器并解压。</p><p>请维护人员先确认服务器系统、网络和所需系统组件已准备好。系统盘以及单独使用的数据盘，都须保留至少 30 GiB 且至少 20% 的可用空间。准备好用户能访问的服务器地址和平台管理员密码。</p><h2 id="安装" tabindex="-1">安装 <a class="header-anchor" href="#安装" aria-label="Permalink to &quot;安装&quot;">​</a></h2><p>在服务器终端进入解压后的安装包目录，执行：</p><div class="language-sh vp-adaptive-theme"><button title="复制代码" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">./install.sh</span></span></code></pre></div><ol><li>需要时输入当前服务器账号的系统密码，以取得安装权限。</li><li>按提示填写程序存放位置、访问地址和端口。默认存放位置为 <code>/opt</code>，程序实际放在 <code>/opt/induframe</code>；公共访问端口默认 <code>443</code>，管理端口默认 <code>18100</code>。使用默认值时按回车。</li><li>证书方式默认由安装器生成；有现成证书时，请维护人员提供所需文件。设置平台超级管理员用户名和密码，默认用户名为 <code>admin</code>；建议密码使用 8–72 个半角英文字母、数字或符号，并输入两次。</li><li>核对终端提示，等待所有阶段完成。遇到替换服务器已有运行环境的询问时，先确认其中没有需要保留的服务和数据。</li></ol><p>终端显示“InduFrame 中心安装完成。”且命令正常结束后，保存公共入口、管理入口和日志路径。用浏览器打开管理入口，以刚设置的平台管理员账号登录，在“组织管理”为标有“默认组织”的组织重置管理员密码；随后从公共入口使用组织管理员账号登录。</p><p>浏览器提示证书不受信任时，请维护人员核对地址和证书后处理。</p><h2 id="更新" tabindex="-1">更新 <a class="header-anchor" href="#更新" aria-label="Permalink to &quot;更新&quot;">​</a></h2><p>更新前安排暂停使用，并由维护人员完成所需数据备份。将新取得的完整安装包解压到另一目录，进入该目录后仍执行：</p><div class="language-sh vp-adaptive-theme"><button title="复制代码" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">./install.sh</span></span></code></pre></div><p>检测到已完成安装的平台后，终端显示 <code>1) 更新</code>、<code>2) 取消</code>。输入 <code>1</code> 开始更新；输入 <code>2</code> 或直接回车取消，平台保持原状。</p><p>更新沿用原安装位置、访问设置和账号，保留平台数据。等待最终完成提示及命令正常结束后，用原账号检查两个入口和需要使用的工程。更新中出现失败提示时，按下方“遇到问题”处理。</p><p>只有交付人员明确提供<strong>小型补丁包</strong>时，才按补丁说明运行该包内的 <code>./update.sh</code>；完整安装包统一使用 <code>./install.sh</code>。</p><h2 id="卸载" tabindex="-1">卸载 <a class="header-anchor" href="#卸载" aria-label="Permalink to &quot;卸载&quot;">​</a></h2><p>在完整安装包目录执行：</p><div class="language-sh vp-adaptive-theme"><button title="复制代码" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ./uninstall.sh</span></span></code></pre></div><p>如果原包已移走，可执行实际程序目录中的卸载脚本。默认位置为 <code>sudo /opt/induframe/uninstall.sh</code>。</p><ol><li>第一次询问是否卸载时，输入 <code>y</code> 继续；输入 <code>n</code> 或回车则取消。</li><li>第二次询问是否删除数据时，输入 <code>n</code> 或回车会<strong>停止服务并保留数据</strong>；输入 <code>y</code> 选择删除。</li><li>选择删除数据还须输入大写 <code>PURGE</code> 确认。删除范围包括平台数据、配置、日志、程序及安装器添加的运行环境；服务器原有的运行环境会另行询问，默认保留。</li></ol><p>等待终端明确报告卸载结果。若报告待核对的采集数据或需另行处理的系统规则，请交给维护人员处理。保留数据后重新安装会再次收集安装设置，原平台继续使用原账号和密码。</p><h2 id="遇到问题" tabindex="-1">遇到问题 <a class="header-anchor" href="#遇到问题" aria-label="Permalink to &quot;遇到问题&quot;">​</a></h2><p>出现失败或中断时，记录最后的阶段、完整提示和日志路径，交给维护人员核对。初次安装未完成时可能询问保留设置或清理本次未完成内容；保留设置便于处理后重试，不代表安装成功。不要自行删除平台数据或安装记录。</p><p>安装或更新完成后，再确认组织登录和所需工程功能正常；卸载完成后，按已选择的数据保留方式办理后续交接。</p>',26)])])}const k=e(o,[["render",l]]);export{u as __pageData,k as default};
